# name: late_minus_early_yes_rate
# description: Yes-rate on trials with trial_index above the median minus yes-rate at or below it; the model has no session dynamics, so observed above null means people become more liberal (more yes) later in the session, below means more conservative.
def test_statistic(df):
    t = df["trial_index"].to_numpy(float)
    y = df["rating"].to_numpy(float)
    med = np.median(t)
    late = t > med
    if late.all() or (~late).all():
        return 0.0
    return float(y[late].mean() - y[~late].mean())

# name: cell_rate_dispersion
# description: Variance across (set, target) cells of the cell's yes-rate (each cell has repeated answers); observed above null means the model's per-cell predictions are too flat/undifferentiated (people discriminate cells more sharply), below means the model is too extreme/deterministic across cells.
def test_statistic(df):
    key = df["number_set"].astype(str) + "|" + df["target"].astype(int).astype(str)
    m = df["rating"].astype(float).groupby(key).mean()
    if len(m) < 2:
        return 0.0
    return float(m.var())

# name: single_example_yes_rate
# description: Yes-rate on trials whose set has exactly one example (target different from it); observed above null means the model still generalizes too narrowly from a single example, below means too broadly.
def test_statistic(df):
    ns = df["number_set"].astype(str)
    one = ~ns.str.contains(",")
    ok = one & (pd.to_numeric(ns, errors="coerce") != df["target"].astype(int))
    if not ok.any():
        return 0.5
    return float(df["rating"][ok].astype(float).mean())

# name: target_in_set_yes_rate
# description: Yes-rate on trials whose target is itself one of the shown examples; the model forces this to ~1, so observed below null means the model over-produces yes for already-seen examples (people are noisier/less certain than any concept-membership account).
def test_statistic(df):
    ns = "," + df["number_set"].astype(str).str.replace(" ", "", regex=False) + ","
    tg = "," + df["target"].astype(int).astype(str) + ","
    inset = np.array([b in a for a, b in zip(ns.to_numpy(), tg.to_numpy())])
    if not inset.any():
        return 1.0
    return float(df["rating"].to_numpy(float)[inset].mean())
